<?php
namespace Tests\Feature;use App\Models\{Institution,Survey,User};use Database\Seeders\{RolesAndPermissionsSeeder,SystemThresholdSeeder};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class DashboardAnalyticsTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed([RolesAndPermissionsSeeder::class,SystemThresholdSeeder::class]);}public function test_metrics_exclude_simulated_values_and_disclose_incomplete_health():void{$u=User::factory()->create();$u->assignRole('Viewer');$i=Institution::create(['name'=>'T','slug'=>'t']);$c=$i->campuses()->create(['name'=>'M','code'=>'M']);$b=$c->buildings()->create(['name'=>'B','code'=>'B']);$f=$b->floors()->create(['name'=>'G','code'=>'G','level_number'=>0]);$fp=$f->floorPlans()->create(['uploaded_by'=>$u->id,'original_name'=>'p','file_path'=>'p','mime_type'=>'image/png','file_size'=>1,'version'=>1]);$s=Survey::create(['floor_id'=>$f->id,'floor_plan_id'=>$fp->id,'created_by'=>$u->id,'name'=>'S']);foreach([[false,50,20,1],[true,999,999,99]] as[$sim,$down,$lat,$loss]){$p=$s->points()->create(['floor_plan_id'=>$fp->id,'captured_by'=>$u->id,'x_normalized'=>.1+($sim?.1:0),'y_normalized'=>.2,'source_type'=>$sim?'simulated':'measured','collection_method'=>'manual','validation_status'=>'valid','captured_at'=>now()]);$p->measurements()->create(['download_mbps'=>$down,'latency_ms'=>$lat,'packet_loss_percent'=>$loss,'source_type'=>$sim?'simulated':'measured','collection_method'=>'manual','is_simulated'=>$sim,'captured_at'=>now()]);}$this->actingAs($u)->getJson('/api/analytics/dashboard')->assertOk()->assertJsonPath('performance.median_download_mbps',50)->assertJsonPath('counts.simulated',1)->assertJsonPath('health.complete',false);}}
